-- Stage 3 data cleanup: Tom's choices on the duplicate review page
-- (https://claude.ai/artifact/WdysxxqDXSD1QAoWnY7x6h, pasted in chat on 21 Oct 2026).
-- Generated by supabase/.local/make_stage3_fix.py from those choices.
--
--   TYPE (44): records with no status get a business type. Internal, Contributor,
--     Community, Council and Media / PR are non-commercial (org_business_types.is_commercial)
--     and stay out of commercial views.
--   NOTEMAILS: text in a contact's email list that is not an address ("[needs research]",
--     "[no email found]", contact-form and Instagram links) moves to the contact's notes.
--   MERGE (17): merge_businesses(src, dst) per pair. Everything on src moves to dst,
--     matching contacts are joined, src becomes 'Not a business' with merged_into = dst.
--     Each merge backs itself up under its own reason ('merge <src> into <dst> at ...').
--   KEEPBOTH pairs: nothing changes.
--
-- TYPE and NOTEMAILS rows are copied to cc_phase0_backup (reason 'stage3_review_2026_10_21')
-- before they change. Needs migration 20261021_003_merge_businesses.
-- Undo: supabase/data-fixes/20261021_stage3_review_undo.sql
-- Run with psql -v ON_ERROR_STOP=1. It refuses to run twice.

BEGIN;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM cc_phase0_backup WHERE reason = 'stage3_review_2026_10_21') THEN
    RAISE EXCEPTION 'stage3_review_2026_10_21 has already been applied';
  END IF;
  IF to_regproc('public.merge_businesses') IS NULL THEN
    RAISE EXCEPTION 'migration 20261021_003_merge_businesses is not applied';
  END IF;
END $$;

