-- Guards: every id is the business Tom saw, nothing is merged twice or into a source,
-- the sources are live and the types exist.
DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM _mv m JOIN businesses s ON s.id = m.src AND s.name = m.src_name
                                   JOIN businesses d ON d.id = m.dst AND d.name = m.dst_name;
  IF n <> 17 THEN RAISE EXCEPTION 'expected 17 merge pairs matching by id and name, found %', n; END IF;
  IF EXISTS (SELECT 1 FROM _mv a JOIN _mv b ON a.dst = b.src) THEN RAISE EXCEPTION 'a target is also a source'; END IF;
  IF EXISTS (SELECT 1 FROM _mv m JOIN businesses b ON b.id IN (m.src, m.dst)
             WHERE b.merged_into IS NOT NULL OR b.status = 'Not a business') THEN
    RAISE EXCEPTION 'a business in a pair is already merged or hidden';
  END IF;
  SELECT count(*) INTO n FROM _ty t JOIN businesses b ON b.id = t.id AND b.name = t.name;
  IF n <> 44 THEN RAISE EXCEPTION 'expected 44 businesses to type matching by id and name, found %', n; END IF;
  IF EXISTS (SELECT 1 FROM _ty t WHERE NOT EXISTS (
               SELECT 1 FROM org_business_types o JOIN businesses b ON b.id = t.id
               WHERE o.org_id = b.organization_id AND o.value = t.t AND o.is_active)) THEN
    RAISE EXCEPTION 'a type is not in the organisation''s business types';
  END IF;
END $$;

-- Contacts holding something that isn't an email address in their email list
CREATE TEMP TABLE _ne ON COMMIT DROP AS
SELECT c.id,
       (SELECT coalesce(jsonb_agg(e), '[]'::jsonb) FROM jsonb_array_elements_text(c.emails) e WHERE e ~ '@') AS keep,
       (SELECT string_agg(e, '; ') FROM jsonb_array_elements_text(c.emails) e WHERE e !~ '@') AS moved
FROM contacts c
WHERE jsonb_typeof(c.emails) = 'array'
  AND EXISTS (SELECT 1 FROM jsonb_array_elements_text(c.emails) e WHERE e !~ '@');

-- 1. Backup
INSERT INTO cc_phase0_backup (table_name, row_id, before_row, reason)
SELECT 'businesses', b.id, to_jsonb(b), 'stage3_review_2026_10_21' FROM businesses b WHERE b.id IN (SELECT id FROM _ty)
UNION ALL
SELECT 'contacts', c.id, to_jsonb(c), 'stage3_review_2026_10_21' FROM contacts c WHERE c.id IN (SELECT id FROM _ne);

-- 2. TYPE
UPDATE businesses b SET business_type = t.t FROM _ty t WHERE b.id = t.id;

-- 3. NOTEMAILS
UPDATE contacts c
SET emails = n.keep,
    normalized_email = CASE WHEN c.normalized_email ~ '@' THEN c.normalized_email ELSE n.keep->>0 END,
    notes = concat_ws(E'\n', nullif(c.notes, ''), 'Was in the email list (moved 21/10/2026): ' || n.moved)
FROM _ne n WHERE c.id = n.id;

-- 4. MERGE, in the order Tom's list gives them
CREATE TEMP TABLE _done (n int, result jsonb) ON COMMIT DROP;
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT * FROM _mv ORDER BY n LOOP
    INSERT INTO _done VALUES (r.n, merge_businesses(r.src, r.dst));
  END LOOP;
END $$;

-- 5. Checks
DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM _mv m JOIN businesses b ON b.id = m.src WHERE b.merged_into = m.dst AND b.status = 'Not a business';
  IF n <> 17 THEN RAISE EXCEPTION 'expected 17 merged sources, found %', n; END IF;
  SELECT count(*) INTO n FROM correspondence WHERE business_id IN (SELECT src FROM _mv);
  IF n > 0 THEN RAISE EXCEPTION '% emails still on a merged business', n; END IF;
  SELECT count(*) INTO n FROM contacts c, jsonb_array_elements_text(c.emails) e WHERE jsonb_typeof(c.emails) = 'array' AND e !~ '@';
  IF n > 0 THEN RAISE EXCEPTION '% non-addresses still in email lists', n; END IF;
END $$;

SELECT 'typed ' || (SELECT count(*) FROM _ty) || ', email lists cleaned ' || (SELECT count(*) FROM _ne)
       || ', merged ' || (SELECT count(*) FROM _done) AS summary;
SELECT d.n, m.src_name || ' -> ' || m.dst_name AS merge,
       d.result->'moved' AS moved, d.result->>'reason' AS undo_reason
FROM _done d JOIN _mv m USING (n) ORDER BY d.n;

COMMIT;
